package com.jbrempresa.backend.dto.administracion;
import java.time.*;import com.fasterxml.jackson.annotation.JsonFormat;import com.jbrempresa.backend.entity.*;import jakarta.validation.constraints.*;
public final class OrganizacionDtos{private OrganizacionDtos(){}
 public record AreaEntrada(@NotBlank @Size(max=30) String areCod,@NotBlank @Size(max=100) String areNom,Long areIdPad){public AreaOrganizativa entidad(){AreaOrganizativa v=new AreaOrganizativa();v.setAreCod(areCod);v.setAreNom(areNom);v.setAreIdPad(areIdPad);return v;}}
 public record AreaSalida(Long areId,Long empId,String areCod,String areNom,Long areIdPad,String areUsuMov,@JsonFormat(pattern="dd/MM/yyyy HH:mm:ss") LocalDateTime areFecMov,Boolean areAct){public static AreaSalida desde(AreaOrganizativa v){return new AreaSalida(v.getAreId(),v.getEmpId(),v.getAreCod(),v.getAreNom(),v.getAreIdPad(),v.getAreUsuMov(),v.getAreFecMov(),v.getAreAct());}}
 public record PersonalEntrada(@NotNull Long areId,@NotNull Long perId,@Size(max=100) String peaCar,Boolean peaRes,Boolean peaPri,LocalDate peaFecDes,LocalDate peaFecHas){public PersonalArea entidad(){PersonalArea v=new PersonalArea();v.setAreId(areId);v.setPerId(perId);v.setPeaCar(peaCar);v.setPeaRes(peaRes);v.setPeaPri(peaPri);v.setPeaFecDes(peaFecDes);v.setPeaFecHas(peaFecHas);return v;}}
 public record PersonalSalida(Long peaId,Long empId,Long areId,Long perId,String peaCar,Boolean peaRes,Boolean peaPri,LocalDate peaFecDes,LocalDate peaFecHas,String peaUsuMov,@JsonFormat(pattern="dd/MM/yyyy HH:mm:ss") LocalDateTime peaFecMov,Boolean peaAct){public static PersonalSalida desde(PersonalArea v){return new PersonalSalida(v.getPeaId(),v.getEmpId(),v.getAreId(),v.getPerId(),v.getPeaCar(),v.getPeaRes(),v.getPeaPri(),v.getPeaFecDes(),v.getPeaFecHas(),v.getPeaUsuMov(),v.getPeaFecMov(),v.getPeaAct());}}
}
